using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// The adaptive score and the ambience, generated by Tools/generate_music.py.
///
/// In the game, three stems play in lockstep (same tempo, length and chords): the mountain
/// arrangement, the forest arrangement and a combat stem of war drums. Walking into the forest
/// cross-fades the tune into its eerie arrangement in time with the backdrop (BiomeBackdrop), and
/// when skeletons close in the drums come in on the beat, then drop out a few seconds after the
/// fight. Night wind or the forest's crickets and owls cross-fade the same way underneath.
///
/// The title screen has its own theme. The player's attacks duck the music a little
/// (AudioDirector.Duck), and it falls away when the wizard dies.
/// </summary>
public class MusicDirector : MonoBehaviour
{
    static MusicDirector instance;

    public static float MusicVolume
    {
        get => PlayerPrefs.GetFloat("MusicVolume", 1f);
        set => PlayerPrefs.SetFloat("MusicVolume", Mathf.Clamp01(value));
    }

    const float MusicLevel = 0.55f;
    const float CombatLevel = 0.6f;
    const float AmbienceLevel = 0.7f;

    AudioSource mountain, forest, combat, menu, ambMountain, ambForest;
    bool inGame;
    float sceneFade;        // 0..1, fading the current scene's music in
    float combatTarget, combatLevel, combatHold;
    float deathFade = 1f;
    bool dead;
    float resync;
    Scene watchedScene;
    float playerCheck;

    /// <summary>Skeletons call this while they fight, with how intense it is (0..1).</summary>
    public static void ReportCombat(float intensity)
    {
        if (instance == null) return;
        instance.combatTarget = Mathf.Max(instance.combatTarget, Mathf.Clamp01(intensity));
        instance.combatHold = 4f;
    }

    /// <summary>The wizard has died: the music falls away.</summary>
    public static void PlayerDied()
    {
        if (instance != null) instance.dead = true;
    }

    void Awake()
    {
        instance = this;
        mountain = MakeSource("music_mountain", "Music");
        forest = MakeSource("music_forest", "Music");
        combat = MakeSource("music_combat", "Music");
        menu = MakeSource("music_menu", "Music");
        ambMountain = MakeSource("amb_mountain", "Ambience");
        ambForest = MakeSource("amb_forest", "Ambience");
    }


    AudioSource MakeSource(string clip, string folder)
    {
        var go = new GameObject(clip);
        go.transform.SetParent(transform, false);
        var src = go.AddComponent<AudioSource>();
        src.playOnAwake = false;
        src.loop = true;
        src.spatialBlend = 0f;
        src.volume = 0f;
        src.clip = Resources.Load<AudioClip>($"{folder}/{clip}");
        src.priority = 0;
        return src;
    }

    // Watches for a new scene (and a player turning up in it) rather than relying on sceneLoaded,
    // which the first scene of a Play session doesn't always raise for an object created this early.
    void WatchScene()
    {
        var scene = SceneManager.GetActiveScene();
        playerCheck -= Time.unscaledDeltaTime;
        if (scene == watchedScene && (inGame || playerCheck > 0f)) return;
        playerCheck = 1f;
        var newScene = scene != watchedScene;
        watchedScene = scene;
        if (!newScene && GameObject.FindWithTag("Player") == null) return;
        OnSceneChanged();
    }

    void OnSceneChanged()
    {
        var wasInGame = inGame;
        // A scene with a player in it is gameplay; anything else (the title screen) gets the theme.
        inGame = GameObject.FindWithTag("Player") != null;
        // A fresh run brings the music back; leaving a run (after a death, say) lets it finish fading.
        if (inGame)
        {
            dead = false;
            deathFade = 1f;
            combatTarget = combatLevel = 0f;
        }
        // Switching between the title theme and the game music: carry on the cross-fade from where
        // it stands, so nothing jumps in volume.
        if (!mountain.isPlaying && !menu.isPlaying) sceneFade = 0f;
        else if (inGame != wasInGame) sceneFade = 1f - sceneFade;

        if (inGame)
        {
            if (!mountain.isPlaying)
            {
                // Started in the same frame they stay together; Update keeps them aligned.
                mountain.Play();
                forest.Play();
                combat.Play();
            }
            if (!ambMountain.isPlaying)
            {
                ambMountain.Play();
                ambForest.Play();
                ambForest.timeSamples = ambMountain.clip != null ? ambMountain.clip.samples / 2 : 0;
            }
        }
        else if (!menu.isPlaying) menu.Play();
    }

    void Update()
    {
        WatchScene();
        var dt = Time.unscaledDeltaTime;
        sceneFade = Mathf.MoveTowards(sceneFade, 1f, dt / 1.5f);
        if (dead) deathFade = Mathf.MoveTowards(deathFade, 0f, dt / 1.2f);

        combatHold -= dt;
        if (combatHold <= 0f) combatTarget = Mathf.MoveTowards(combatTarget, 0f, dt / 2f);
        // The drums come in over a bar or so and leave more slowly.
        combatLevel = Mathf.MoveTowards(combatLevel, dead ? 0f : combatTarget, dt / (combatTarget > combatLevel ? 1.2f : 3f));

        var duck = 1f - 0.3f * AudioDirector.Duck;
        var music = MusicVolume * MusicLevel * duck * deathFade;
        var ambience = MusicVolume * AmbienceLevel * (1f - 0.25f * AudioDirector.Duck);
        var gameFade = inGame ? sceneFade : 1f - sceneFade;
        var menuFade = inGame ? 1f - sceneFade : sceneFade;

        // Equal-power cross-fade between the biomes, following the backdrop.
        var forestAmount = Mathf.Clamp01(BiomeBackdrop.CurrentForest);
        var toMountain = Mathf.Cos(forestAmount * Mathf.PI * 0.5f);
        var toForest = Mathf.Sin(forestAmount * Mathf.PI * 0.5f);
        var underFight = 1f - 0.2f * combatLevel;

        SetVolume(mountain, music * toMountain * underFight * gameFade);
        SetVolume(forest, music * toForest * underFight * gameFade);
        SetVolume(combat, music * CombatLevel / MusicLevel * combatLevel * gameFade);
        SetVolume(menu, MusicVolume * MusicLevel * menuFade);
        SetVolume(ambMountain, ambience * toMountain * gameFade);
        SetVolume(ambForest, ambience * toForest * gameFade);

        // Stop what has faded out, so the stems restart together next time.
        if (!inGame && sceneFade >= 1f && mountain.isPlaying)
        {
            mountain.Stop();
            forest.Stop();
            combat.Stop();
            ambMountain.Stop();
            ambForest.Stop();
        }
        if (inGame && sceneFade >= 1f && menu.isPlaying) menu.Stop();

        // Keep the stems locked to the mountain track.
        resync -= dt;
        if (resync <= 0f && mountain.isPlaying)
        {
            resync = 1f;
            Align(forest);
            Align(combat);
        }
    }

    void Align(AudioSource stem)
    {
        if (!stem.isPlaying || stem.clip == null || mountain.clip == null) return;
        var drift = Mathf.Abs(stem.timeSamples - mountain.timeSamples);
        if (drift > mountain.clip.frequency * 0.03f && drift < mountain.clip.samples / 2)
            stem.timeSamples = mountain.timeSamples;
    }

    static void SetVolume(AudioSource src, float volume)
    {
        if (src.clip == null) return;
        src.volume = Mathf.Clamp01(volume);
    }
}
